use atlas_native_storage_contract::{create_workspace,workspace_lock};
use std::{fs,process::{Command,Stdio},time::{Duration,SystemTime,UNIX_EPOCH},thread};
#[test] fn child_lock(){if let Ok(path)=std::env::var("LOCK_CHILD_ROOT"){let guard=workspace_lock(std::path::Path::new(&path)).unwrap();fs::write(std::path::Path::new(&path).join("acquired"),b"yes").unwrap();if std::env::var_os("LOCK_CHILD_WAIT").is_some(){thread::sleep(Duration::from_secs(30));}drop(guard);}}
#[test] fn lock_across_processes_and_kill(){let p=std::env::temp_dir().join(format!("atlas-lock-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()));create_workspace(&p).unwrap();let guard=workspace_lock(&p).unwrap();let exe=std::env::current_exe().unwrap();let mut child=Command::new(&exe).args(["--exact","child_lock","--nocapture"]).env("LOCK_CHILD_ROOT",&p).stdout(Stdio::null()).spawn().unwrap();thread::sleep(Duration::from_millis(300));assert!(!p.join("acquired").exists());drop(guard);assert!(child.wait().unwrap().success());assert!(p.join("acquired").exists());fs::remove_file(p.join("acquired")).unwrap();let mut child=Command::new(exe).args(["--exact","child_lock","--nocapture"]).env("LOCK_CHILD_ROOT",&p).env("LOCK_CHILD_WAIT","1").stdout(Stdio::null()).spawn().unwrap();for _ in 0..100 {if p.join("acquired").exists(){break}thread::sleep(Duration::from_millis(20));}assert!(p.join("acquired").exists());child.kill().unwrap();child.wait().unwrap();let guard=workspace_lock(&p).unwrap();drop(guard);fs::remove_dir_all(p).unwrap();}
#[cfg(unix)] #[test] fn symlink_lock_refused(){use std::os::unix::fs::symlink;let p=std::env::temp_dir().join(format!("atlas-link-lock-{}",std::process::id()));create_workspace(&p).unwrap();let target=p.join("target");fs::write(&target,b"safe").unwrap();symlink(&target,p.join(".atlas-operation.lock")).unwrap();assert!(workspace_lock(&p).is_err());fs::remove_dir_all(p).unwrap();}
